package com.acme.salary.config;
import com.acme.salary.entity.*; import com.acme.salary.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@Configuration public class SeedConfig { @Bean CommandLineRunner seed(EmployeeRepository employees,FxRateRepository fx){return args->{LocalDate date=LocalDate.of(2026,1,1); Map<String,BigDecimal> rates=Map.of("USD",BigDecimal.ONE,"EUR",new BigDecimal("1.08"),"GBP",new BigDecimal("1.27"),"INR",new BigDecimal("0.0119"),"SGD",new BigDecimal("0.78"),"AUD",new BigDecimal("0.66")); rates.forEach((c,r)->fx.save(new FxRate(c,date,r))); if(employees.count()>0)return; String[] countries={"India","USA","UK","Germany","Singapore","Australia"}; String[] currencies={"INR","USD","GBP","EUR","SGD","AUD"}; String[] departments={"Engineering","Finance","HR","Sales","Operations","Product"}; var batch=new ArrayList<Employee>(1000); for(int i=1;i<=10000;i++){Employee e=new Employee(); e.setEmployeeNumber(String.format("ACME-%05d",i));e.setFirstName("Employee");e.setLastName(String.format("%05d",i));e.setDepartment(departments[(i-1)%departments.length]);e.setCountry(countries[(i-1)%countries.length]);e.setCurrency(currencies[(i-1)%currencies.length]);e.setAnnualSalary(new BigDecimal(30000+(i%120)*750));e.setEffectiveDate(date);batch.add(e);if(batch.size()==1000){employees.saveAll(batch);batch.clear();}}if(!batch.isEmpty())employees.saveAll(batch);};}}
